// Run: node scripts/brand-assets.mjs  (rebuilds every SVG in assets/ from the sources in assets/brand/)
//
// Sources, editable with scripts/brand-pixel-editor.html (import / export as JSON rows):
//   master-52.json  the 52-cell master: Scale2x of the 26-cell draft with the concave centre ('b' blue, 'w' bone)
//   draft-26.json   the 26-cell draft, used as is by the TUI splash and the 32 px favicon
//   cut-16.json     the hand-drawn 16-cell cut for 16 px favicons
//   outlines.json   outlined text (Cinzel, EB Garamond), regenerated by scripts/brand-outlines.py
import {readFileSync, writeFileSync} from 'node:fs';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const assets = join(root, 'assets');
const read = name => JSON.parse(readFileSync(join(assets, 'brand', name), 'utf8'));
const master = read('master-52.json'), draft = read('draft-26.json'), cut16 = read('cut-16.json'), outlines = read('outlines.json');

// Upper case = highlight, lower case = base, d/e = shadow.
const DARK = {B: '#97B5E8', b: '#7DA1DE', d: '#6688C8', W: '#F4F1EA', w: '#E8E4DA', e: '#CCC7BB'};       // on NIGHT
const LIGHT = {B: '#6487CF', b: '#4A6FBA', d: '#3A5CA3', W: '#46516A', w: '#2B3447', e: '#1D2432'};      // on PAPER
const NIGHT = '#121722', PAPER = '#F5F3EE', BONE = '#E8E4DA', INK = '#2B3447';
const mono = colour => Object.fromEntries([...'BbdWwe'].map(key => [key, colour]));

/** One-pixel rim light on edges facing the top left and shadow on edges facing the bottom right; then any tone pixel
 * without a same-tone neighbour goes back to the base colour, so light reads as edges, not dots on every stair step. */
function shade(grid) {
  const n = grid.length, at = (x, y) => grid[y]?.[x] ?? '.';
  const LIT = {b: 'B', w: 'W'}, DIM = {b: 'd', w: 'e'};
  const toned = grid.map((row, y) => [...row].map((c, x) => {
    if (c === '.') return c;
    const lit = (at(x - 1, y) !== c && at(x, y - 1) !== c) || (at(x - 1, y - 1) === '.' && (at(x - 1, y) !== c || at(x, y - 1) !== c));
    const dark = (at(x + 1, y) !== c && at(x, y + 1) !== c) || (at(x + 1, y + 1) === '.' && (at(x + 1, y) !== c || at(x, y + 1) !== c));
    return lit && !dark ? LIT[c] : dark && !lit ? DIM[c] : c;
  }));
  const base = {B: 'b', d: 'b', W: 'w', e: 'w'};
  return toned.map((row, y) => row.map((t, x) => {
    if (!base[t]) return t;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if ((dx || dy) && toned[y + dy]?.[x + dx] === t) return t;
    return base[t];
  }).join('')).slice(0, n);
}

/** Pixel rows as run-length rects. */
function pixels(rows, palette, x0 = 0, y0 = 0, cell = 1) {
  const out = [];
  rows.forEach((row, y) => {
    for (let start = 0, x = 1; x <= row.length; x++) {
      if (x < row.length && row[x] === row[start]) continue;
      if (row[start] !== '.') out.push(`<rect x="${+(x0 + start * cell).toFixed(2)}" y="${+(y0 + y * cell).toFixed(2)}" width="${+((x - start) * cell).toFixed(2)}" height="${+cell.toFixed(2)}" fill="${palette[row[start]]}"/>`);
      start = x;
    }
  });
  return `<g shape-rendering="crispEdges">${out.join('')}</g>`;
}

/** Outlined text at `size` (font units scaled), left edge x, baseline y. Returns [svg, advance]. */
function text(face, value, size, x, y, fill, tracking = 0) {
  const k = size / face.upm, parts = [];
  let pen = 0;
  for (const ch of value) {
    const glyph = face.glyphs[ch];
    if (!glyph) throw new Error(`outlines.json has no glyph for ${JSON.stringify(ch)}; rerun scripts/brand-outlines.py`);
    if (glyph.d) parts.push(`<path transform="matrix(${k} 0 0 ${-k} ${+(x + pen).toFixed(2)} ${+y.toFixed(2)})" d="${glyph.d}"/>`);
    pen += glyph.advance * k + tracking * size;
  }
  return [`<g fill="${fill}">${parts.join('')}</g>`, pen - tracking * size];
}

/** The master's centre (ring and core), cropped: it stands in for the wordmark's second O. */
function core() {
  const c = master.length / 2;
  const kept = master.map((row, y) => [...row].map((p, x) => Math.abs(x + 0.5 - c) + Math.abs(y + 0.5 - c) <= 12.5 ? p : '.').join(''));
  const live = kept.filter(row => row.replace(/\./g, ''));
  const left = Math.min(...live.map(row => row.search(/[^.]/))), right = Math.max(...live.map(row => row.replace(/\.+$/, '').length));
  return live.map(row => row.slice(left, right));
}

/** LOG, the pixel core, X: cap height 100, baseline y=100. Returns [svg, width]. */
function wordmark(ink, palette) {
  const face = outlines.wordmark, size = face.upm * 100 / face.capHeight, track = 0.12 * size;
  let x = 0;
  const parts = [];
  for (const ch of 'LOG') { const [svg, w] = text(face, ch, size, x, 100, ink); parts.push(svg); x += w + track; }
  const crop = core(), height = 94, cell = height / crop.length, oWidth = face.glyphs.O.advance * size / face.upm;
  parts.push(pixels(crop, palette, x + (oWidth - crop[0].length * cell) / 2, (100 - height) / 2, cell));
  x += oWidth + track;
  const [svg, w] = text(face, 'X', size, x, 100, ink);
  parts.push(svg);
  return [parts.join(''), x + w];
}

// ---- Monospace text (Maple Mono CN outlines) for the ensemble row and the README stage ----------------------------
const scene = read('scene.json');
// Actor identity colours from src/actors/profiles/*/config.yaml (dark) and darker cuts of the same hues for paper.
const CAST_DARK = {logox: '#7DA1DE', techne: '#E5C07B', kalon: '#B3A0D4', aletheia: '#7FAE99', anamnesis: '#C9D7F2'};
const CAST_LIGHT = {logox: '#3F64AE', techne: '#8F6512', kalon: '#6B55A0', aletheia: '#2F6B52', anamnesis: '#4A5F8A'};
// The stage is drawn in the logox-dark theme (src/config/themes/logox-dark.json).
const SCENE_TONES = {...CAST_DARK, fg: '#E8E6E0', muted: '#969EB0', user: '#D77757', success: '#8CC59E', running: '#E5C07B'};

// Symbol geometry: centre (300, 300), half-size R; strokes of weight S.
const R = 320, S = 72, C = 300, CY = 330;
const diamond = r => `M${C} ${CY + r}L${C + r} ${CY}L${C} ${CY - r}L${C - r} ${CY}Z`;
const circle = r => `M${C - r} ${CY}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0Z`;
const box = (x0, y0, x1, y1) => `M${x0} ${y0}H${x1}V${y1}H${x0}Z`;
const star = (r, w) => `M${C} ${CY + r}Q${C + w} ${CY + w} ${C + r} ${CY}Q${C + w} ${CY - w} ${C} ${CY - r}Q${C - w} ${CY - w} ${C - r} ${CY}Q${C - w} ${CY + w} ${C} ${CY + r}Z`;
const SYMBOLS = {
  '◈': diamond(R + 20) + diamond(R + 20 - S * 1.3) + diamond(R * 0.42),
  '⊞': (() => {const a = R - 40, i = a - S, h = S / 2; return box(C - a, CY - a, C + a, CY + a) + box(C - i, CY - i, C + i, CY + i)
    + box(C - h, CY - i, C + h, CY + i) + box(C - i, CY - h, C - h, CY + h) + box(C + h, CY - h, C + i, CY + h);})(),
  '✧': star(R + 20, 52) + star(R + 20 - S * 1.6, 22),
  '◎': circle(R) + circle(R - S) + circle(R * 0.36),
  '◇': diamond(R + 20) + diamond(R + 20 - S * 1.3),
  '⏵': `M${C - 170} ${CY + R - 70}L${C + 230} ${CY}L${C - 170} ${CY - R + 70}Z`,
};

/** Glyph paths go into <defs> once per file and are placed with <use>, so a repeated character costs one short element. */
function monoWriter(prefix) {
  const defs = new Map();
  const id = (face, ch) => {
    const key = prefix + (face === outlines.monoBold ? 'b' : 'r') + ch.codePointAt(0).toString(16);
    if (!defs.has(key)) defs.set(key, `<path id="${key}" d="${face.glyphs[ch].d}"/>`);
    return key;
  };
  /** The actor symbols and ⏵, drawn at one size in a 600 × 1000 cell (font units, y up, baseline 0): the font's own are small and uneven. */
  const drawn = Object.fromEntries(Object.entries(SYMBOLS).map(([ch, d]) => [ch, () => `<path fill-rule="evenodd" d="${d}"/>`]));
  /** Spans [[text, colour, bold?]] from left edge x on baseline y at `size` px; returns [svg, width]. */
  const line = (spans, size, x, y) => {
    const k = size / outlines.mono.upm, out = [];
    let pen = 0;
    for (const [value, fill, bold] of spans) {
      const face = bold ? outlines.monoBold : outlines.mono, cells = [];
      for (const ch of value) {
        const at = +(x + pen).toFixed(2);
        if (drawn[ch]) cells.push(`<g transform="matrix(${k} 0 0 ${-k} ${at} ${+y.toFixed(2)})">${drawn[ch]()}</g>`);
        else if (ch !== ' ') {
          if (!face.glyphs[ch]) throw new Error(`outlines.json has no mono glyph for ${JSON.stringify(ch)}; rerun scripts/brand-outlines.py`);
          if (face.glyphs[ch].d) cells.push(`<use href="#${id(face, ch)}" transform="matrix(${k} 0 0 ${-k} ${at} ${+y.toFixed(2)})"/>`);
        }
        pen += (drawn[ch] || ch === ' ' ? 600 : face.glyphs[ch].advance) * k;
      }
      if (cells.length) out.push(`<g fill="${fill}">${cells.join('')}</g>`);
    }
    return [out.join(''), pen];
  };
  return {line, defs: () => `<defs>${[...defs.values()].join('')}</defs>`};
}

/** The ensemble row of the classic banner: one tag per actor, separated by hairlines like the TUI's actor bar. */
function ensembleRow(writer, cast, rule, x, y, size, maxWidth) {
  const tags = scene.pills.map(([symbol, name, key]) => writer.line([[symbol + ' ' + name, cast[key], true]], size, 0, 0));
  const natural = tags.reduce((sum, [, w]) => sum + w, 0), gap = (maxWidth - natural) / (tags.length - 1);
  let pen = x;
  const out = [];
  tags.forEach(([, w], i) => {
    const [svg] = writer.line([[scene.pills[i][0] + ' ' + scene.pills[i][1], cast[scene.pills[i][2]], true]], size, pen, y);
    out.push(svg);
    if (i < tags.length - 1) out.push(`<line x1="${+(pen + w + gap / 2).toFixed(1)}" y1="${+(y - size * 0.82).toFixed(1)}" x2="${+(pen + w + gap / 2).toFixed(1)}" y2="${+(y + size * 0.22).toFixed(1)}" stroke="${rule}"/>`);
    pen += w + gap;
  });
  return out.join('');
}

function bannerClassic(palette, bg, ink, muted, rule, cast, prefix) {
  const W = 1280, H = 400, left = 492, writer = monoWriter(prefix);
  const [word, width] = wordmark(ink, palette), s = Math.min(1, (W - left - 84) / width), top = (H - (100 * s + 128)) / 2;
  const [tagline] = text(outlines.tagline, outlines.tagline.text, 34, left, top + 100 * s + 58, ink);
  const ruleY = top + 100 * s + 82, row = ensembleRow(writer, cast, rule, left, top + 100 * s + 128, 22, width * s);
  return [`${writer.defs()}<rect width="${W}" height="${H}" rx="22" fill="${bg}"/>${pixels(shade(master), palette, 92, (H - 52 * 6) / 2, 6)}`
    + `<g transform="translate(${left} ${top.toFixed(1)}) scale(${s.toFixed(4)})">${word}</g>${tagline}`
    + `<line x1="${left}" y1="${ruleY.toFixed(1)}" x2="${(left + width * s).toFixed(1)}" y2="${ruleY.toFixed(1)}" stroke="${rule}"/>${row}`, W, H];
}

function banner(palette, ink, cast, mode) {
  const isDark = mode === 'd';
  const railBg = isDark ? '#182131' : '#E8E4DA';
  const tick = isDark ? '#3A4862' : '#C8C2B5';

  const W = 1280, H = 392;
  const padX = 10, padTop = 6, padBot = 12;
  const cardW = W - padX * 2, cardH = H - padTop - padBot, cardR = 22;
  const cy = padTop + cardH / 2;

  const cell = 6, gridSize = 52 * cell, visFlower = 48 * cell, mPad = 2 * cell;
  const [word, wordW] = wordmark(ink, palette);
  const scale = 0.78, scaledWordW = wordW * scale, wordH = 100 * scale;

  const gap = 88;
  const visLeft = Math.round((W - (visFlower + gap + scaledWordW)) / 2);
  const markGridX = visLeft - mPad, markGridY = Math.round(cy - gridSize / 2);
  const rightX = visLeft + visFlower + gap;

  const taglineSize = 29, taglineOffset = 39, tracksOffset = 65;
  const trackH = 4, trackStep = 9, tracksTotalH = 3 * trackStep + trackH;
  const stackTotalH = wordH + tracksOffset + tracksTotalH;

  const wordTop = Math.round(cy - stackTotalH / 2);
  const wordBase = wordTop + wordH;
  const taglineY = wordBase + taglineOffset;
  const scoreY = wordBase + tracksOffset;

  const [taglineSvg] = text(outlines.tagline, outlines.tagline.text, taglineSize, rightX, taglineY, ink);

  const defs = `<defs>`
    + `<clipPath id="card-clip-${mode}"><rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" rx="${cardR}"/></clipPath>`
    + `<filter id="card-elev-${mode}" x="-3%" y="-6%" width="106%" height="118%">`
    + `<feDropShadow dx="0" dy="3" stdDeviation="3.5" flood-color="${isDark ? '#04060A' : '#2B3447'}" flood-opacity="${isDark ? '0.38' : '0.075'}"/>`
    + `</filter>`
    + `<radialGradient id="dome-${mode}" cx="46%" cy="38%" r="76%" fx="42%" fy="30%">`
    + `<stop offset="0%" stop-color="${isDark ? '#1A2334' : '#FCFBF8'}"/>`
    + `<stop offset="40%" stop-color="${isDark ? '#161E2D' : '#F8F6F1'}"/>`
    + `<stop offset="75%" stop-color="${isDark ? '#121825' : '#F3F0E9'}"/>`
    + `<stop offset="100%" stop-color="${isDark ? '#0F141F' : '#ECE8DF'}"/>`
    + `</radialGradient>`
    + `<linearGradient id="edge-v-${mode}" x1="0" y1="0" x2="0" y2="1">`
    + `<stop offset="0%" stop-color="${isDark ? '#43587E' : '#FFFFFF'}" stop-opacity="${isDark ? '0.24' : '0.75'}"/>`
    + `<stop offset="4.5%" stop-color="${isDark ? '#324361' : '#FFFFFF'}" stop-opacity="0"/>`
    + `<stop offset="93%" stop-color="${isDark ? '#070A10' : '#B8B0A0'}" stop-opacity="0"/>`
    + `<stop offset="100%" stop-color="${isDark ? '#070A10' : '#AFA694'}" stop-opacity="${isDark ? '0.24' : '0.18'}"/>`
    + `</linearGradient>`
    + `<linearGradient id="edge-h-${mode}" x1="0" y1="0" x2="1" y2="0">`
    + `<stop offset="0%" stop-color="${isDark ? '#090C14' : '#BDB5A4'}" stop-opacity="${isDark ? '0.14' : '0.10'}"/>`
    + `<stop offset="3.5%" stop-color="${isDark ? '#090C14' : '#BDB5A4'}" stop-opacity="0"/>`
    + `<stop offset="96.5%" stop-color="${isDark ? '#080B12' : '#B3AA98'}" stop-opacity="0"/>`
    + `<stop offset="100%" stop-color="${isDark ? '#080B12' : '#ADA492'}" stop-opacity="${isDark ? '0.18' : '0.12'}"/>`
    + `</linearGradient>`
    + `<linearGradient id="sheen-${mode}" x1="0.10" y1="0.0" x2="0.72" y2="1.0">`
    + `<stop offset="0%" stop-color="#FFFFFF" stop-opacity="0"/>`
    + `<stop offset="28%" stop-color="${isDark ? '#9DBAE8' : '#FFFFFF'}" stop-opacity="${isDark ? '0.02' : '0.18'}"/>`
    + `<stop offset="44%" stop-color="${isDark ? '#C5DAFA' : '#FFFFFF'}" stop-opacity="${isDark ? '0.065' : '0.45'}"/>`
    + `<stop offset="58%" stop-color="${isDark ? '#9DBAE8' : '#FFFFFF'}" stop-opacity="${isDark ? '0.02' : '0.15'}"/>`
    + `<stop offset="78%" stop-color="#FFFFFF" stop-opacity="0"/>`
    + `<stop offset="100%" stop-color="#FFFFFF" stop-opacity="0"/>`
    + `</linearGradient>`
    + `<linearGradient id="top-catch-${mode}" x1="0" y1="0" x2="1" y2="0">`
    + `<stop offset="0%" stop-color="${isDark ? '#8AB0EB' : '#FFFFFF'}" stop-opacity="0"/>`
    + `<stop offset="20%" stop-color="${isDark ? '#8AB0EB' : '#FFFFFF'}" stop-opacity="${isDark ? '0.32' : '0.88'}"/>`
    + `<stop offset="50%" stop-color="${isDark ? '#B7D0F5' : '#FFFFFF'}" stop-opacity="${isDark ? '0.45' : '1.00'}"/>`
    + `<stop offset="80%" stop-color="${isDark ? '#8AB0EB' : '#FFFFFF'}" stop-opacity="${isDark ? '0.26' : '0.82'}"/>`
    + `<stop offset="100%" stop-color="${isDark ? '#8AB0EB' : '#FFFFFF'}" stop-opacity="0"/>`
    + `</linearGradient>`
    + `<linearGradient id="rim-${mode}" x1="0.08" y1="0" x2="0.92" y2="1">`
    + `<stop offset="0%" stop-color="${isDark ? '#5A739E' : '#FFFFFF'}" stop-opacity="${isDark ? '0.52' : '0.95'}"/>`
    + `<stop offset="45%" stop-color="${isDark ? '#28344A' : '#E2DDD2'}" stop-opacity="${isDark ? '0.42' : '0.65'}"/>`
    + `<stop offset="100%" stop-color="${isDark ? '#0B0F17' : '#C9C2B3'}" stop-opacity="${isDark ? '0.72' : '0.65'}"/>`
    + `</linearGradient>`
    + `<pattern id="dotgrid-${mode}" width="20" height="20" patternUnits="userSpaceOnUse">`
    + `<circle cx="10" cy="10" r="0.85" fill="${isDark ? '#3B4A66' : '#CFC8BA'}" opacity="${isDark ? '0.28' : '0.38'}"/>`
    + `</pattern>`
    + `<radialGradient id="dotmask-grad-${mode}" cx="50%" cy="50%" r="50%">`
    + `<stop offset="60%" stop-color="#FFFFFF" stop-opacity="1"/><stop offset="96%" stop-color="#FFFFFF" stop-opacity="0"/>`
    + `</radialGradient>`
    + `<mask id="dotmask-${mode}"><rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" fill="url(#dotmask-grad-${mode})"/></mask>`
    + `</defs>`;

  const mX = padX + 26, mY = padTop + 24, tLen = 10;
  const ticks = [
    `M${mX} ${mY + tLen}V${mY}H${mX + tLen}`,
    `M${padX + cardW - 26 - tLen} ${mY}H${padX + cardW - 26}V${mY + tLen}`,
    `M${mX} ${padTop + cardH - 24 - tLen}V${padTop + cardH - 24}H${mX + tLen}`,
    `M${padX + cardW - 26 - tLen} ${padTop + cardH - 24}H${padX + cardW - 26}V${padTop + cardH - 24 - tLen}`,
  ].map(d => `<path d="${d}" fill="none" stroke="${tick}" stroke-width="1.2" opacity="0.52"/>`).join('');

  const promptSize = 16, promptGlyph = outlines.mono.glyphs['❯'], pk = promptSize / outlines.mono.upm;
  const promptY = scoreY + tracksTotalH / 2 + (730 * pk) / 2;
  const promptSvg = `<path transform="matrix(${pk} 0 0 ${-pk} ${rightX} ${promptY.toFixed(1)})" d="${promptGlyph.d}" fill="${cast.logox}"/>`;

  const trackX = rightX + 24, trackW = Math.round(scaledWordW) - 24;
  const tracks = [
    [cast.logox, [[0.00, 0.16, 0.95], [0.22, 0.28, 0.45], [0.56, 0.34, 0.95], [0.94, 0.06, 0.55]]],
    [cast.techne, [[0.08, 0.36, 0.90], [0.50, 0.19, 0.85], [0.74, 0.14, 0.40]]],
    [cast.kalon, [[0.14, 0.22, 0.88], [0.42, 0.31, 0.92], [0.79, 0.17, 0.55]]],
    [cast.aletheia, [[0.24, 0.15, 0.70], [0.46, 0.18, 0.90], [0.70, 0.26, 0.92]]],
  ];
  const tracksSvg = tracks.map(([color, segs], idx) => {
    const ty = scoreY + idx * trackStep;
    const base = `<rect x="${trackX}" y="${ty}" width="${trackW}" height="${trackH}" rx="1.5" fill="${railBg}"/>`;
    const bars = segs.map(([s, w, op]) =>
      `<rect x="${+(trackX + s * trackW).toFixed(1)}" y="${ty}" width="${+(w * trackW).toFixed(1)}" height="${trackH}" rx="1.5" fill="${color}" opacity="${op}"/>`
    ).join('');
    return base + bars;
  }).join('');

  return [
    defs
    + `<rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="url(#dome-${mode})" filter="url(#card-elev-${mode})"/>`
    + `<g clip-path="url(#card-clip-${mode})">`
    + `<rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="url(#edge-v-${mode})"/>`
    + `<rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="url(#edge-h-${mode})"/>`
    + `<rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="url(#sheen-${mode})"/>`
    + `<rect x="${padX}" y="${padTop}" width="${cardW}" height="${cardH}" fill="url(#dotgrid-${mode})" mask="url(#dotmask-${mode})"/>`
    + ticks
    + `<rect x="${padX + 0.75}" y="${padTop + 0.75}" width="${cardW - 1.5}" height="${cardH - 1.5}" rx="${cardR - 0.5}" fill="none" stroke="url(#rim-${mode})" stroke-width="1.5"/>`
    + `<rect x="${padX + cardR}" y="${padTop + 1.5}" width="${cardW - cardR * 2}" height="1.2" fill="url(#top-catch-${mode})"/>`
    + `</g>`
    + pixels(shaded, palette, markGridX, markGridY, cell)
    + `<g transform="translate(${rightX} ${wordTop}) scale(${scale})">${word}</g>`
    + taglineSvg + promptSvg + tracksSvg,
    W,
    H,
  ];
}

/** The README stage: a terminal window with one round of the ensemble at work, drawn in the logox-dark theme. */
function stage() {
  const W = 1200, size = 19, lh = 33, pad = 44, writer = monoWriter('s'), T = SCENE_TONES;
  const spans = line => line.map(([value, tone]) => [value, T[tone], ['logox', 'techne', 'kalon', 'aletheia', 'anamnesis'].includes(tone) && /[A-Za-z]/.test(value)]);
  const bar = 46, bodyTop = bar + 40, rows = scene.stage.length, composerY = bodyTop + rows * lh + 30, statusY = composerY + 64, H = statusY + 40;
  const out = [];
  // Window, title bar and a soft shadow (no gradients on the mark; the window is an illustration).
  out.push(`<rect x="6" y="10" width="${W - 12}" height="${H - 12}" rx="16" fill="#0B0E14" opacity="0.55"/>`);
  out.push(`<rect width="${W}" height="${H - 8}" rx="16" fill="#1C2330" stroke="#2C3546"/>`);
  out.push(`<path d="M16 0h${W - 32}a16 16 0 0 1 16 16v${bar - 16}h-${W}v-${bar - 16}a16 16 0 0 1 16 -16z" fill="#161C27"/><line x1="0" y1="${bar}" x2="${W}" y2="${bar}" stroke="#2C3546"/>`);
  out.push(pixels(draft, DARK, 22, 10, 1));
  const [title, tw] = writer.line([[scene.title, '#8E97A8']], 15, 0, 0);
  out.push(`<g transform="translate(${((W - tw) / 2).toFixed(1)} ${bar / 2 + 5})">${title}</g>`);
  // Body: one rail per card in the owner's colour, as in the timeline.
  scene.stage.forEach((line, i) => {
    const y = bodyTop + i * lh, rail = scene.rails[i];
    // A card's rail runs unbroken over its lines and stops 4 px short of the next card.
    const first = rail && scene.rails[i - 1] !== rail, last = rail && scene.rails[i + 1] !== rail;
    if (rail) out.push(`<rect x="${pad}" y="${y - lh + 9 + (first ? 2 : 0)}" width="3" height="${lh - (first ? 2 : 0) - (last ? 4 : 0)}" fill="${T[rail]}" opacity="${rail === 'logox' ? 0.9 : 0.75}"/>`);
    out.push(writer.line(spans(line), size, pad + (rail ? 22 : 0), y)[0]);
  });
  // Composer and the actor bar.
  out.push(`<line x1="${pad}" y1="${composerY - 34}" x2="${W - pad}" y2="${composerY - 34}" stroke="#2C3546"/>`);
  out.push(writer.line(spans(scene.composer), size, pad, composerY)[0]);
  out.push(`<rect x="${pad + writer.line(spans(scene.composer), size, 0, 0)[1] + 2}" y="${composerY - size * 0.85}" width="${size * 0.55}" height="${size * 1.1}" fill="#E8E6E0" opacity="0.85"/>`);
  out.push(`<line x1="${pad}" y1="${statusY - 30}" x2="${W - pad}" y2="${statusY - 30}" stroke="#2C3546"/>`);
  let pen = pad;
  scene.status.forEach((cell, i) => {
    const [svg, w] = writer.line(spans(cell), 16, pen, statusY);
    out.push(svg);
    pen += w + 28;
    if (i < scene.status.length - 1) {out.push(`<line x1="${pen - 14}" y1="${statusY - 14}" x2="${pen - 14}" y2="${statusY + 4}" stroke="#3A4558"/>`); }
  });
  return [writer.defs() + out.join(''), W, H];
}

function lockup(palette, ink) {
  const cell = 5, size = 52 * cell, gap = 64, [word, width] = wordmark(ink, palette);
  return [pixels(shade(master), palette, 0, 0, cell) + `<g transform="translate(${size + gap} ${(size - 100) / 2})">${word}</g>`, size + gap + width, size];
}

const files = {};
const svg = (name, title, body, w, h, scale = 1) => {
  files[name] = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${+w.toFixed(2)} ${+h.toFixed(2)}" width="${+(w * scale).toFixed(2)}" height="${+(h * scale).toFixed(2)}" role="img" aria-label="${title}"><title>${title}</title>${body}</svg>\n`;
};
const shaded = shade(master);
svg('logo-mark.svg', 'LOGOX', pixels(shaded, DARK), 52, 52, 8);
svg('logo-mark-light.svg', 'LOGOX', pixels(shaded, LIGHT), 52, 52, 8);
svg('logo-mark-mono.svg', 'LOGOX', pixels(master, mono(NIGHT)), 52, 52, 8);
svg('logo-mark-reversed.svg', 'LOGOX', pixels(master, mono(BONE)), 52, 52, 8);
svg('logo-mark-16.svg', 'LOGOX', pixels(cut16, DARK), 16, 16, 2);
svg('logo-mark-16-light.svg', 'LOGOX', pixels(cut16, LIGHT), 16, 16, 2);
svg('app-icon.svg', 'LOGOX', `<rect width="64" height="64" rx="14" fill="${NIGHT}"/>${pixels(shaded, DARK, 6, 6)}`, 64, 64, 8);
svg('favicon.svg', 'LOGOX', `<rect width="18" height="18" rx="4" fill="${NIGHT}"/>${pixels(cut16, DARK, 1, 1)}`, 18, 18);
svg('favicon-32.svg', 'LOGOX', `<rect width="32" height="32" rx="7" fill="${NIGHT}"/>${pixels(draft, DARK, 3, 3)}`, 32, 32);
for (const [name, palette, ink] of [['wordmark.svg', DARK, BONE], ['wordmark-light.svg', LIGHT, INK]]) {
  const [body, w] = wordmark(ink, palette);
  svg(name, 'LOGOX', `<g transform="translate(0 4)">${body}</g>`, w, 108);
}
for (const [name, palette, ink] of [['logo.svg', DARK, BONE], ['logo-light.svg', LIGHT, INK]]) svg(name, 'LOGOX', ...lockup(palette, ink));
svg('banner.svg', 'LOGOX: A terminal coding ensemble', ...banner(DARK, BONE, CAST_DARK, 'd'));
svg('banner-light.svg', 'LOGOX: A terminal coding ensemble', ...banner(LIGHT, INK, CAST_LIGHT, 'l'));
svg('banner-classic.svg', 'LOGOX: A terminal coding ensemble', ...bannerClassic(DARK, NIGHT, BONE, '#8E97A8', '#2A3446', CAST_DARK, 'cd'));
svg('banner-classic-light.svg', 'LOGOX: A terminal coding ensemble', ...bannerClassic(LIGHT, PAPER, INK, '#6B7385', '#D9D5CB', CAST_LIGHT, 'cl'));
svg('stage.svg', 'Logox at work: the Director splits a request and three actors work on it in parallel', ...stage());
for (const [name, content] of Object.entries(files)) writeFileSync(join(assets, name), content);
console.log(`wrote ${Object.keys(files).length} files to assets/`);
